@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:assignment-tests;MODE=MySQL;DB_CLOSE_DELAY=-1","app.assignments.max-file-bytes=4096","app.exams.expiry-enabled=false"})
@AutoConfigureMockMvc @DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS)
class AssignmentManagementTests {
 static final Path root;
 static{try{root=Files.createTempDirectory("eduflow-homework-test-");}catch(IOException ex){throw new ExceptionInInitializerError(ex);}}
 @DynamicPropertySource static void storage(DynamicPropertyRegistry r){r.add("app.assignments.storage-dir",()->root.toString());}
 @Autowired MockMvc mvc;@Autowired ObjectMapper mapper;@Autowired JwtService jwt;
 @Autowired AssignmentRepository assignments;@Autowired AssignmentRecipientRepository recipients;@Autowired AssignmentAttachmentRepository teachingFiles;
 @Autowired AssignmentSubmissionRepository submissions;@Autowired SubmissionAttachmentRepository submissionFiles;@Autowired SubmissionRevisionRepository revisions;@Autowired SubmissionGradeHistoryRepository grades;
 @Autowired UserRepository users;@Autowired StudentRepository students;@Autowired TeacherRepository teachers;@Autowired CourseRepository courses;@Autowired BatchRepository batches;@Autowired BatchEnrollmentRepository enrollments;@Autowired BatchTeacherAssignmentRepository teacherAssignments;
 @MockitoBean(name="assignmentClock")Clock clock;@MockitoSpyBean AssignmentFileStorage storage;
 @MockitoSpyBean AssignmentFileValidator validator;
 final AtomicReference<Instant> time=new AtomicReference<>();final Instant initial=Instant.parse("2026-11-11T09:00:00Z");
 String admin,teacher,unassigned,student,otherStudent,ineligible,parent;Long batchId,studentId,otherId;
 @BeforeEach void setup()throws Exception{
  time.set(initial);when(clock.instant()).thenAnswer(x->time.get());clean();
  var ad=users.saveAndFlush(new User("Admin","admin@homework.test","unused",Role.ADMIN));admin=jwt.generateToken(ad.getEmail());
  var tu=users.saveAndFlush(new User("Teacher","teacher@homework.test","unused",Role.TEACHER));teacher=jwt.generateToken(tu.getEmail());
  users.saveAndFlush(new User("Other teacher","otherteacher@homework.test","unused",Role.TEACHER));unassigned=jwt.generateToken("otherteacher@homework.test");
  var su=users.saveAndFlush(new User("Asha","student@homework.test","unused",Role.STUDENT));student=jwt.generateToken(su.getEmail());
  var ou=users.saveAndFlush(new User("Other","other@homework.test","unused",Role.STUDENT));otherStudent=jwt.generateToken(ou.getEmail());
  var iu=users.saveAndFlush(new User("Not enrolled","no@homework.test","unused",Role.STUDENT));ineligible=jwt.generateToken(iu.getEmail());
  users.saveAndFlush(new User("Parent","parent@homework.test","unused",Role.PARENT));parent=jwt.generateToken("parent@homework.test");
  var c=new Course();c.setCode("HW");c.setName("Homework course");c.setDurationWeeks(12);courses.saveAndFlush(c);
  var b=new Batch();b.setCode("HW-B");b.setName("Homework batch");b.setCourse(c);b.setCapacity(20);b.setStartDate(LocalDate.of(2026,10,1));b.setEndDate(LocalDate.of(2027,1,1));b.setStatus(BatchStatus.ACTIVE);batches.saveAndFlush(b);batchId=b.getId();
  var t=new Teacher();t.setFullName("Teacher");t.setEmployeeId("HW-T");t.setEmail("faculty@homework.test");t.setUser(tu);teachers.saveAndFlush(t);var ta=new BatchTeacherAssignment();ta.setBatch(b);ta.setTeacher(t);teacherAssignments.saveAndFlush(ta);
  studentId=makeStudent("HW-1",su,b,true);otherId=makeStudent("HW-2",ou,b,true);makeStudent("HW-3",iu,b,false);
 }
 @Test void fileValidationCannotBypassTheServerDeadline()throws Exception{
  long id=published(false);time.set(initial.plusSeconds(3599));
  doAnswer(call->{var value=call.callRealMethod();time.set(initial.plusSeconds(3600));return value;}).when(validator).validate(any(org.springframework.web.multipart.MultipartFile.class));
  mvc.perform(multipartCreate(id,"",upload("answer.png",png())).header("Authorization","Bearer "+student)).andExpect(status().isConflict());
  assertThat(submissions.count()).isZero();assertThat(submissionFiles.count()).isZero();
  try(var files=Files.list(root)){assertThat(files.count()).isZero();}
 }
 Long makeStudent(String code,User user,Batch batch,boolean enroll){var s=new Student(code);s.setFullName(user.getFullName());s.setEmail(code+"@school.test");s.setPhone("9876543210");s.setDateOfBirth(LocalDate.of(2008,1,1));s.setAdmissionDate(LocalDate.of(2026,10,1));s.setAddress("Address");s.setGuardianName("Guardian");s.setGuardianPhone("9876543211");s.setUser(user);students.saveAndFlush(s);if(enroll){var e=new BatchEnrollment();e.setBatch(batch);e.setStudent(s);e.setEnrollmentDate(LocalDate.of(2026,10,1));enrollments.saveAndFlush(e);}return s.getId();}
 @AfterEach void clean()throws Exception{grades.deleteAll();revisions.deleteAll();submissionFiles.deleteAll();submissions.deleteAll();teachingFiles.deleteAll();recipients.deleteAll();assignments.deleteAll();teacherAssignments.deleteAll();enrollments.deleteAll();teachers.deleteAll();students.deleteAll();batches.deleteAll();courses.deleteAll();users.deleteAll();try(var files=Files.list(root)){for(var file:files.toList())Files.delete(file);}}
 MockHttpServletRequestBuilder json(MockHttpServletRequestBuilder b,Object data,String token)throws Exception{return b.header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsString(data));}
 JsonNode body(MvcResult r)throws Exception{return mapper.readTree(r.getResponse().getContentAsString());}
 Map<String,Object> input(boolean late){return new HashMap<>(Map.of("title","Algebra homework","description","Show your working","batchId",batchId,"maxMarks",100,"dueDateTime",initial.plusSeconds(3600).toString(),"allowLateSubmission",late));}
 JsonNode create(boolean late)throws Exception{return body(mvc.perform(json(post("/api/assignments"),input(late),admin)).andExpect(status().isCreated()).andReturn());}
 JsonNode getAssignment(long id)throws Exception{return body(mvc.perform(get("/api/assignments/"+id).header("Authorization","Bearer "+admin)).andExpect(status().isOk()).andReturn());}
 long version(long id)throws Exception{return getAssignment(id).get("version").asLong();}
 long published(boolean late)throws Exception{long id=create(late).get("id").asLong();mvc.perform(json(post("/api/assignments/"+id+"/publish"),Map.of("version",version(id)),teacher)).andExpect(status().isOk());return id;}
 JsonNode submit(long id,String text,String token)throws Exception{return body(mvc.perform(json(post("/api/assignments/"+id+"/submissions"),Map.of("submissionText",text),token)).andExpect(status().isCreated()).andReturn());}
 JsonNode getSubmission(long id)throws Exception{return body(mvc.perform(get("/api/assignments/submissions/"+id).header("Authorization","Bearer "+student)).andExpect(status().isOk()).andReturn());}
 byte[] png()throws Exception{var out=new ByteArrayOutputStream();ImageIO.write(new BufferedImage(2,2,BufferedImage.TYPE_INT_RGB),"png",out);return out.toByteArray();}
 byte[] jpg()throws Exception{var out=new ByteArrayOutputStream();ImageIO.write(new BufferedImage(2,2,BufferedImage.TYPE_INT_RGB),"jpg",out);return out.toByteArray();}
 byte[] pdf()throws Exception{try(var doc=new PDDocument();var out=new ByteArrayOutputStream()){doc.addPage(new PDPage());doc.save(out);return out.toByteArray();}}
 byte[] docx(boolean unsafe)throws Exception{var out=new ByteArrayOutputStream();try(var zip=new ZipOutputStream(out)){var parts=new LinkedHashMap<String,String>();parts.put("[Content_Types].xml","<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Override PartName=\"/word/document.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml\"/></Types>");parts.put("_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"word/document.xml\"/></Relationships>");parts.put("word/document.xml","<w:document xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:body/></w:document>");if(unsafe)parts.put("../escape","bad");for(var entry:parts.entrySet()){zip.putNextEntry(new ZipEntry(entry.getKey()));zip.write(entry.getValue().getBytes(java.nio.charset.StandardCharsets.UTF_8));zip.closeEntry();}}return out.toByteArray();}
 MockMultipartFile upload(String name,byte[] bytes){return new MockMultipartFile("files",name,"application/octet-stream",bytes);}
 MockMultipartHttpServletRequestBuilder multipartCreate(long id,String text,MockMultipartFile... files)throws Exception{var builder=multipart("/api/assignments/"+id+"/submissions").file(new MockMultipartFile("data","data","application/json",mapper.writeValueAsBytes(Map.of("submissionText",text))));for(var f:files)builder.file(f);return builder;}
 @Test void createValidateDeadlineAndAuthenticatedActor()throws Exception{var r=input(false);r.put("createdBy",99999);mvc.perform(json(post("/api/assignments"),r,teacher)).andExpect(status().isCreated()).andExpect(jsonPath("createdBy").value("Teacher"));r.put("dueDateTime",initial.toString());mvc.perform(json(post("/api/assignments"),r,admin)).andExpect(status().isBadRequest());r.put("dueDateTime",initial.plusSeconds(3600).toString());r.put("maxMarks",-1);mvc.perform(json(post("/api/assignments"),r,admin)).andExpect(status().isBadRequest());}
 @Test void roleChecksAndUnrelatedTeacherDenied()throws Exception{long id=create(false).get("id").asLong();for(String token:List.of(unassigned,student,parent)){mvc.perform(json(post("/api/assignments"),input(false),token)).andExpect(status().isForbidden());mvc.perform(get("/api/assignments/"+id).header("Authorization","Bearer "+token)).andExpect(status().isForbidden());}mvc.perform(get("/api/assignments")).andExpect(status().isUnauthorized());}
 @Test void publishingSnapshotsOnlyEligibleRosterAndHidesDrafts()throws Exception{long id=create(false).get("id").asLong();mvc.perform(get("/api/assignments").header("Authorization","Bearer "+student)).andExpect(jsonPath("totalElements").value(0));mvc.perform(json(post("/api/assignments/"+id+"/publish"),Map.of("version",version(id)),teacher)).andExpect(status().isOk()).andExpect(jsonPath("counts.eligible").value(2));mvc.perform(get("/api/assignments").header("Authorization","Bearer "+student)).andExpect(jsonPath("totalElements").value(1));mvc.perform(get("/api/assignments/"+id).header("Authorization","Bearer "+ineligible)).andExpect(status().isForbidden());}
 @Test void invalidTransitionsAndPublishedRulesAreImmutable()throws Exception{long id=create(false).get("id").asLong();mvc.perform(json(post("/api/assignments/"+id+"/close"),Map.of("version",version(id)),admin)).andExpect(status().isConflict());time.set(initial.plusSeconds(3601));mvc.perform(json(post("/api/assignments/"+id+"/publish"),Map.of("version",version(id)),teacher)).andExpect(status().isConflict());time.set(initial);long published=published(false);var input=input(false);input.put("version",version(published));mvc.perform(json(put("/api/assignments/"+published),input,admin)).andExpect(status().isConflict());}
 @Test void eligibleTextSubmissionAndDuplicateRejected()throws Exception{long id=published(false);submit(id,"My working",student);mvc.perform(json(post("/api/assignments/"+id+"/submissions"),Map.of("submissionText","Duplicate"),student)).andExpect(status().isConflict());assertThat(submissions.count()).isEqualTo(1);mvc.perform(json(post("/api/assignments/"+id+"/submissions"),Map.of("submissionText","Not enrolled"),ineligible)).andExpect(status().isForbidden());}
 @Test void emptyWorkAndLateDisabledRejected()throws Exception{long id=published(false);mvc.perform(json(post("/api/assignments/"+id+"/submissions"),Map.of("submissionText","  "),student)).andExpect(status().isBadRequest());assertThat(submissions.count()).isZero();time.set(initial.plusSeconds(3600));mvc.perform(json(post("/api/assignments/"+id+"/submissions"),Map.of("submissionText","Late"),student)).andExpect(status().isConflict());}
 @Test void lateAllowedAndNoPostDeadlineResubmission()throws Exception{long id=published(true);time.set(initial.plusSeconds(3601));var s=submit(id,"Late working",student);assertThat(s.get("status").asText()).isEqualTo("LATE");mvc.perform(json(put("/api/assignments/submissions/"+s.get("id").asLong()),Map.of("version",s.get("version").asLong(),"submissionText","Change"),student)).andExpect(status().isConflict());}
 @Test void closedAssignmentsRejectNewWorkAndPreserveOwnedHistory()throws Exception{long id=published(false);var s=submit(id,"Work",student);mvc.perform(json(post("/api/assignments/"+id+"/close"),Map.of("version",version(id)),teacher)).andExpect(status().isOk());mvc.perform(json(post("/api/assignments/"+id+"/submissions"),Map.of("submissionText","New"),otherStudent)).andExpect(status().isConflict());mvc.perform(get("/api/assignments/"+id).header("Authorization","Bearer "+student)).andExpect(status().isOk());mvc.perform(get("/api/assignments/"+id).header("Authorization","Bearer "+otherStudent)).andExpect(status().isForbidden());getSubmission(s.get("id").asLong());}
 @Test void resubmissionPreservesPreviousTextAndRejectsStaleVersion()throws Exception{long id=published(false);var s=submit(id,"Original work",student);long sid=s.get("id").asLong();var update=Map.of("version",s.get("version").asLong(),"submissionText","Revised work");mvc.perform(json(put("/api/assignments/submissions/"+sid),update,student)).andExpect(status().isOk());mvc.perform(json(put("/api/assignments/submissions/"+sid),update,student)).andExpect(status().isConflict());mvc.perform(get("/api/assignments/submissions/"+sid+"/history").header("Authorization","Bearer "+student)).andExpect(jsonPath("revisions[0].submissionText").value("Original work"));assertThat(submissions.count()).isEqualTo(1);}
 @Test void atomicFileOnlyCreationAndContentTypeValidation()throws Exception{long id=published(false);var s=body(mvc.perform(multipartCreate(id,"",upload("answer.pdf",pdf())).header("Authorization","Bearer "+student)).andExpect(status().isCreated()).andExpect(jsonPath("attachments[0].contentType").value("application/pdf")).andReturn());assertThat(s.toString()).doesNotContain("storageKey",root.toString());mvc.perform(get("/api/assignments/submission-attachments/"+s.at("/attachments/0/id").asLong()+"/download").header("Authorization","Bearer "+student)).andExpect(status().isOk()).andExpect(header().string("X-Content-Type-Options","nosniff")).andExpect(content().contentType("application/pdf"));}
 @Test void assignmentAttachmentsAcceptActualPngPdfAndDocx()throws Exception{long id=create(false).get("id").asLong();mvc.perform(multipart("/api/assignments/"+id+"/attachments").file(upload("diagram.png",png())).file(upload("sheet.pdf",pdf())).file(upload("instructions.docx",docx(false))).file(upload("photo.jpg",jpg())).param("version",Long.toString(version(id))).header("Authorization","Bearer "+teacher)).andExpect(status().isOk()).andExpect(jsonPath("$.length()").value(4));long file=teachingFiles.findAll().getFirst().getId();mvc.perform(get("/api/assignments/attachments/"+file+"/download").header("Authorization","Bearer "+student)).andExpect(status().isForbidden());mvc.perform(json(post("/api/assignments/"+id+"/publish"),Map.of("version",version(id)),admin)).andExpect(status().isOk());mvc.perform(get("/api/assignments/attachments/"+file+"/download").header("Authorization","Bearer "+student)).andExpect(status().isOk());mvc.perform(get("/api/assignments/attachments/"+file+"/download").header("Authorization","Bearer "+ineligible)).andExpect(status().isForbidden());}
 @Test void rejectsSpoofedUnsupportedOversizedAndTraversalUploads()throws Exception{long id=published(false);for(var file:List.of(upload("code.exe",new byte[]{1}),upload("fake.pdf","not a pdf".getBytes()),upload("fake.png","not an image".getBytes()),upload("../answer.pdf",pdf()),upload("C:\\answer.pdf",pdf()),upload("evil.docx",docx(true))))mvc.perform(multipartCreate(id,"",file).header("Authorization","Bearer "+student)).andExpect(status().isBadRequest());mvc.perform(multipartCreate(id,"",upload("large.pdf",new byte[4097])).header("Authorization","Bearer "+student)).andExpect(status().isPayloadTooLarge());assertThat(submissions.count()).isZero();assertThat(submissionFiles.count()).isZero();try(var files=Files.list(root)){assertThat(files.count()).isZero();}assertThatThrownBy(()->storage.read("../outside")).isInstanceOf(IllegalArgumentException.class);}
 @Test void uploadRollbackRemovesOrphanedFiles()throws Exception{long id=published(false);var calls=new AtomicInteger();doAnswer(call->{if(calls.incrementAndGet()==2)throw new AssignmentStorageException(new IOException("Simulated storage failure"));return call.callRealMethod();}).when(storage).put(any(byte[].class));mvc.perform(multipartCreate(id,"Work",upload("one.png",png()),upload("two.png",png())).header("Authorization","Bearer "+student)).andExpect(status().isInternalServerError());assertThat(submissions.count()).isZero();assertThat(submissionFiles.count()).isZero();try(var files=Files.list(root)){assertThat(files.count()).isZero();}}
 @Test void removedFilesAreArchivedAndRemainPrivateInHistory()throws Exception{long id=published(false);var s=body(mvc.perform(multipartCreate(id,"",upload("original.png",png())).header("Authorization","Bearer "+student)).andExpect(status().isCreated()).andReturn());long sid=s.get("id").asLong(),fid=s.at("/attachments/0/id").asLong();mvc.perform(json(put("/api/assignments/submissions/"+sid),Map.of("version",s.get("version").asLong(),"submissionText","Replacement text","keepAttachmentIds",List.of()),student)).andExpect(status().isOk()).andExpect(jsonPath("attachments").isEmpty());mvc.perform(get("/api/assignments/submissions/"+sid+"/history").header("Authorization","Bearer "+student)).andExpect(jsonPath("revisions[0].attachments[0].id").value(fid));mvc.perform(get("/api/assignments/submission-attachments/"+fid+"/download").header("Authorization","Bearer "+student)).andExpect(status().isOk());mvc.perform(get("/api/assignments/submission-attachments/"+fid+"/download").header("Authorization","Bearer "+otherStudent)).andExpect(status().isForbidden());assertThat(submissionFiles.count()).isEqualTo(1);}
 @Test void cannotRemoveOnlyFileAndLeaveEmptyWork()throws Exception{long id=published(false);var s=body(mvc.perform(multipartCreate(id,"",upload("answer.png",png())).header("Authorization","Bearer "+student)).andExpect(status().isCreated()).andReturn());mvc.perform(json(put("/api/assignments/submissions/"+s.get("id").asLong()),Map.of("version",s.get("version").asLong(),"submissionText","","keepAttachmentIds",List.of()),student)).andExpect(status().isBadRequest());assertThat(revisions.count()).isZero();}
 @Test void gradingValidatesMarksRoleAndPreventsStudentEdits()throws Exception{long id=published(false);var s=submit(id,"Working",student);long sid=s.get("id").asLong();for(int marks:List.of(-1,101))mvc.perform(json(put("/api/assignments/submissions/"+sid+"/grade"),Map.of("version",0,"obtainedMarks",marks),teacher)).andExpect(status().isBadRequest());for(String token:List.of(student,otherStudent,unassigned,parent))mvc.perform(json(put("/api/assignments/submissions/"+sid+"/grade"),Map.of("version",0,"obtainedMarks",85),token)).andExpect(status().isForbidden());mvc.perform(json(put("/api/assignments/submissions/"+sid+"/grade"),Map.of("version",0,"obtainedMarks",85,"feedback","Good work"),teacher)).andExpect(status().isOk()).andExpect(jsonPath("gradedBy").value("Teacher"));s=getSubmission(sid);mvc.perform(json(put("/api/assignments/submissions/"+sid),Map.of("version",s.get("version").asLong(),"submissionText","Altered"),student)).andExpect(status().isConflict());mvc.perform(multipart("/api/assignments/submissions/"+sid+"/attachments").file(upload("extra.png",png())).param("version",s.get("version").asText()).header("Authorization","Bearer "+student)).andExpect(status().isConflict());}
 @Test void gradeCorrectionsRequireReasonAndPreserveAudit()throws Exception{long id=published(false);long sid=submit(id,"Working",student).get("id").asLong();mvc.perform(json(put("/api/assignments/submissions/"+sid+"/grade"),Map.of("version",0,"obtainedMarks",75,"feedback","Initial feedback"),admin)).andExpect(status().isOk());var s=getSubmission(sid);mvc.perform(json(put("/api/assignments/submissions/"+sid+"/grade"),Map.of("version",s.get("version").asLong(),"obtainedMarks",85),teacher)).andExpect(status().isBadRequest());mvc.perform(json(put("/api/assignments/submissions/"+sid+"/grade"),Map.of("version",s.get("version").asLong(),"obtainedMarks",85,"feedback","Rechecked","reason","Rechecked question 2"),teacher)).andExpect(status().isOk());mvc.perform(get("/api/assignments/submissions/"+sid+"/history").header("Authorization","Bearer "+student)).andExpect(jsonPath("grades.length()").value(2)).andExpect(jsonPath("grades[0].previousMarks").value(75)).andExpect(jsonPath("grades[0].reason").value("Rechecked question 2"));}
 @Test void allSubmissionEndpointsEnforceOwnership()throws Exception{long id=published(false);long sid=submit(id,"Private work",student).get("id").asLong();for(String url:List.of("/api/assignments/submissions/"+sid,"/api/assignments/submissions/"+sid+"/attachments","/api/assignments/submissions/"+sid+"/history"))for(String token:List.of(otherStudent,unassigned,parent))mvc.perform(get(url).header("Authorization","Bearer "+token)).andExpect(status().isForbidden());mvc.perform(get("/api/assignments/"+id+"/submissions").header("Authorization","Bearer "+student)).andExpect(status().isForbidden());mvc.perform(get("/api/assignments/"+id+"/pending-recipients").header("Authorization","Bearer "+student)).andExpect(status().isForbidden());}
 @Test void statisticsUseEligibleSnapshotAndNeverDoubleCountRevisions()throws Exception{long id=published(false);mvc.perform(get("/api/assignments/stats").header("Authorization","Bearer "+admin)).andExpect(jsonPath("pendingSubmissions").value(2)).andExpect(jsonPath("completionPercentage").value(0));var s=submit(id,"First",student);long sid=s.get("id").asLong();mvc.perform(get("/api/assignments").param("pendingOnly","true").header("Authorization","Bearer "+student)).andExpect(jsonPath("totalElements").value(0));mvc.perform(get("/api/assignments").param("pendingOnly","true").header("Authorization","Bearer "+otherStudent)).andExpect(jsonPath("totalElements").value(1));mvc.perform(json(put("/api/assignments/submissions/"+sid),Map.of("version",0,"submissionText","Second"),student)).andExpect(status().isOk());mvc.perform(json(put("/api/assignments/submissions/"+sid+"/grade"),Map.of("version",getSubmission(sid).get("version").asLong(),"obtainedMarks",85),teacher)).andExpect(status().isOk());mvc.perform(get("/api/assignments/stats").header("Authorization","Bearer "+teacher)).andExpect(status().isOk()).andExpect(jsonPath("eligibleSubmissions").value(2)).andExpect(jsonPath("submittedAssignments").value(1)).andExpect(jsonPath("pendingSubmissions").value(1)).andExpect(jsonPath("completionPercentage").value(50)).andExpect(jsonPath("averageMarks").value(85));mvc.perform(get("/api/assignments/stats").header("Authorization","Bearer "+otherStudent)).andExpect(jsonPath("submittedAssignments").value(0)).andExpect(jsonPath("pendingSubmissions").value(1));}
 @Test void zeroDataAndOverdueAndFiltersAreTruthful()throws Exception{mvc.perform(get("/api/assignments/stats").header("Authorization","Bearer "+admin)).andExpect(jsonPath("completionPercentage").isEmpty()).andExpect(jsonPath("averageMarks").isEmpty());published(false);time.set(initial.plusSeconds(3601));mvc.perform(get("/api/assignments/stats").header("Authorization","Bearer "+student)).andExpect(jsonPath("overdueAssignments").value(1));mvc.perform(get("/api/assignments").param("fromDate","2026-11-11").param("toDate","2026-11-11").param("search","Algebra").param("batchId",batchId.toString()).header("Authorization","Bearer "+teacher)).andExpect(jsonPath("totalElements").value(1));mvc.perform(get("/api/assignments").param("fromDate","2026-11-12").param("toDate","2026-11-11").header("Authorization","Bearer "+admin)).andExpect(status().isBadRequest());}
 @Test void duplicateConcurrentSubmissionIsPrevented()throws Exception{long id=published(false);var start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){Callable<Integer> run=()->{start.await();return mvc.perform(json(post("/api/assignments/"+id+"/submissions"),Map.of("submissionText","Work"),student)).andReturn().getResponse().getStatus();};var one=pool.submit(run);var two=pool.submit(run);start.countDown();assertThat(List.of(one.get(20,TimeUnit.SECONDS),two.get(20,TimeUnit.SECONDS))).containsExactlyInAnyOrder(201,409);assertThat(submissions.count()).isEqualTo(1);}}
}
